import hmac
import hashlib
import base64
import json
import time
import os
from flask import Flask, request, jsonify, abort
import secrets

app = Flask(__name__)

# Configuration
SECRET_KEY = os.environ.get('JWT_SECRET', secrets.token_hex(32))
TOKEN_EXPIRY = 3600  # 1 hour
MAX_PAYLOAD_SIZE = 4096

def base64url_encode(data):
    """RFC 7515 compliant base64url encoding"""
    if isinstance(data, str):
        data = data.encode('utf-8')
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def base64url_decode(data):
    """RFC 7515 compliant base64url decoding"""
    if isinstance(data, str):
        data = data.encode('ascii')
    # Add padding
    padding = 4 - len(data) % 4
    if padding != 4:
        data += b'=' * padding
    return base64.urlsafe_b64decode(data)

def create_token(payload):
    """Create a signed JWT token"""
    header = {"alg": "HS256", "typ": "JWT"}
    header_b64 = base64url_encode(json.dumps(header, separators=(',', ':')))

    payload['iat'] = int(time.time())
    payload['exp'] = int(time.time()) + TOKEN_EXPIRY
    payload_b64 = base64url_encode(json.dumps(payload, separators=(',', ':')))

    signing_input = header_b64 + b'.' + payload_b64
    signature = hmac.new(SECRET_KEY.encode(), signing_input, hashlib.sha256).digest()
    sig_b64 = base64url_encode(signature)

    return (signing_input + b'.' + sig_b64).decode('ascii')

def verify_signature(token_parts):
    """Verify the JWT signature - returns True if valid"""
    try:
        header_b64, payload_b64, sig_b64 = token_parts
        signing_input = header_b64.encode('ascii') + b'.' + payload_b64.encode('ascii')

        expected_sig = hmac.new(
            SECRET_KEY.encode(), signing_input, hashlib.sha256
        ).digest()

        provided_sig = base64url_decode(sig_b64)

        # Constant-time comparison to prevent timing attacks
        return hmac.compare_digest(expected_sig, provided_sig)
    except Exception:
        return False

def validate_token(token):
    """Full token validation including expiry and structure checks"""
    if not token or not isinstance(token, str):
        return None, "Missing token"

    if len(token) > MAX_PAYLOAD_SIZE:
        return None, "Token too large"

    parts = token.split('.')
    if len(parts) != 3:
        return None, "Invalid token structure"

    # Decode and validate header
    try:
        header = json.loads(base64url_decode(parts[0]))
    except (json.JSONDecodeError, Exception):
        return None, "Invalid header"

    # Algorithm validation
    if header.get('alg') != 'HS256':
        return None, "Unsupported algorithm"

    if header.get('typ') != 'JWT':
        return None, "Invalid token type"

    # Verify signature BEFORE parsing payload
    if not verify_signature(parts):
        return None, "Invalid signature"

    # Decode payload
    try:
        payload = json.loads(base64url_decode(parts[1]))
    except (json.JSONDecodeError, Exception):
        return None, "Invalid payload"

    # Check expiration
    exp = payload.get('exp')
    if not isinstance(exp, (int, float)):
        return None, "Missing expiration"

    if time.time() >= exp:
        return None, "Token expired"

    return payload, None

def check_permission(payload, required_role):
    """Check if the token payload grants the required role"""
    user_roles = payload.get('roles', [])
    if not isinstance(user_roles, list):
        return False

    # Normalize role names for comparison
    normalized_required = required_role.strip().lower()
    for role in user_roles:
        if not isinstance(role, str):
            continue
        normalized_role = role.strip().lower()
        # Exact match only - no role hierarchy
        if normalized_role == normalized_required:
            return True
    return False

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user and issue token"""
    data = request.get_json(force=False, silent=True)
    if not data:
        return jsonify({"error": "Invalid request"}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    # Simulated auth check (in production, use bcrypt/argon2)
    if not authenticate_user(username, password):
        return jsonify({"error": "Invalid credentials"}), 401

    roles = get_user_roles(username)
    token = create_token({"sub": username, "roles": roles})
    return jsonify({"token": token})

@app.route('/api/admin/users', methods=['GET'])
def admin_list_users():
    """Admin endpoint - list all users"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({"error": "Missing authorization"}), 401

    token = auth_header[7:]
    payload, error = validate_token(token)
    if error:
        return jsonify({"error": error}), 401

    if not check_permission(payload, 'admin'):
        return jsonify({"error": "Insufficient permissions"}), 403

    return jsonify({"users": get_all_users()})

@app.route('/api/profile', methods=['GET'])
def get_profile():
    """Get current user's profile"""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({"error": "Missing authorization"}), 401

    token = auth_header[7:]
    payload, error = validate_token(token)
    if error:
        return jsonify({"error": error}), 401

    username = payload.get('sub')
    return jsonify({"profile": get_user_profile(username)})

